run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=203.0.113.0/24 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --enable-logging --description=allow_mail+sat_mail
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=203.0.113.0/24 --dest-ip-ranges=172.16.20.25/32 --layer4-configs=tcp:25 --enable-logging --description=allow_mail+sat_mail
